require '/app/config/environment'
require 'json'
callback = Reaction._commit_callbacks.find { |item| item.filter == :broadcast_reactions }
conditions = callback.instance_variable_get(:@if)
result = { callbacks: Reaction._commit_callbacks.map(&:filter), conditions: {} }
[:create, :destroy].each do |action|
  record = Reaction.allocate
  record.define_singleton_method(:transaction_include_any_action?) { |wanted| wanted.include?(action) }
  record.instance_variable_set(:@_new_record_before_last_commit, action == :create)
  record.instance_variable_set(:@destroyed, action == :destroy)
  result[:conditions][action] = conditions.map { |condition| record.instance_exec(&condition) }
end
result[:reference_types] = %w[comment_id creator_id].to_h { |name| [name, Reaction.columns_hash[name].type] }
result[:target_type] = Comment.columns_hash['id'].type
puts JSON.pretty_generate(result)
